/*
E = 1/`σ_N`²`E_I` + ∑_(j for j>1) α_j²/`σ_S`_j² + ∑_(j for j>1) β_j²/`σ_T`_j²  + ∑_j (ρ_j-ρ̄_j)²/`σ_ρ`_j²
        where
        `σ_N`: ℝ
        `E_I`: ℝ
        α_i : ℝ
        β_i : ℝ
        `σ_S`_i: ℝ
        `σ_T`_i: ℝ
        ρ_i: ℝ
        ρ̄_i: ℝ
        `σ_ρ`_i: ℝ
        ā_i: ℝ 
*/
#include <Eigen/Core>
#include <Eigen/QR>
#include <Eigen/Dense>
#include <Eigen/Sparse>
#include <iostream>
#include <set>
#include <algorithm>

struct heartlib {
    using DT = double;
    using MatrixD = Eigen::MatrixXd;
    using VectorD = Eigen::VectorXd;
    DT E;

    heartlib(
        const double & σ_N,
        const double & E_I,
        const std::vector<double> & α,
        const std::vector<double> & β,
        const std::vector<double> & σ_S,
        const std::vector<double> & σ_T,
        const std::vector<double> & ρ,
        const std::vector<double> & ρ̄,
        const std::vector<double> & σ_ρ,
        const std::vector<double> & ā)
    {
        const long dim_0 = α.size();
        assert( β.size() == dim_0 );
        assert( σ_S.size() == dim_0 );
        assert( σ_T.size() == dim_0 );
        assert( ρ.size() == dim_0 );
        assert( ρ̄.size() == dim_0 );
        assert( σ_ρ.size() == dim_0 );
        assert( ā.size() == dim_0 );
        // E = 1/`σ_N`²`E_I` + ∑_(j for j>1) α_j²/`σ_S`_j² + ∑_(j for j>1) β_j²/`σ_T`_j²  + ∑_j (ρ_j-ρ̄_j)²/`σ_ρ`_j²
        DT sum_0 = 0;
        for(int j=1; j<=σ_S.size(); j++){
            if(j > 1){
                sum_0 += pow(α.at(j-1), 2) / DT(pow(σ_S.at(j-1), 2));
            }
        }
        DT sum_1 = 0;
        for(int j=1; j<=σ_T.size(); j++){
            if(j > 1){
                sum_1 += pow(β.at(j-1), 2) / DT(pow(σ_T.at(j-1), 2));
            }
        }
        DT sum_2 = 0;
        for(int j=1; j<=σ_ρ.size(); j++){
            sum_2 += pow((ρ.at(j-1) - ρ̄.at(j-1)), 2) / DT(pow(σ_ρ.at(j-1), 2));
        }
        E = 1 / DT(pow(σ_N, 2)) * E_I + sum_0 + sum_1 + sum_2;
    }
};

