function output = heartlib(sigma_N, E_I, alpha, beta, sigma_S, sigma_T, rho, rho_bar, sigma_rho, latin_small_letter_a_with_macron)
% output = heartlib(`σ_N`, `E_I`, α, β, `σ_S`, `σ_T`, ρ, ρ̄, `σ_ρ`, ā)
%
%    E = 1/`σ_N`²`E_I` + ∑_(j for j>1) α_j²/`σ_S`_j² + ∑_(j for j>1) β_j²/`σ_T`_j²  + ∑_j (ρ_j-ρ̄_j)²/`σ_ρ`_j²
%            where
%            `σ_N`: ℝ
%            `E_I`: ℝ
%            α_i : ℝ
%            β_i : ℝ
%            `σ_S`_i: ℝ
%            `σ_T`_i: ℝ
%            ρ_i: ℝ
%            ρ̄_i: ℝ
%            `σ_ρ`_i: ℝ
%            ā_i: ℝ 
    alpha = reshape(alpha,[],1);
    beta = reshape(beta,[],1);
    sigma_S = reshape(sigma_S,[],1);
    sigma_T = reshape(sigma_T,[],1);
    rho = reshape(rho,[],1);
    rho_bar = reshape(rho_bar,[],1);
    sigma_rho = reshape(sigma_rho,[],1);
    latin_small_letter_a_with_macron = reshape(latin_small_letter_a_with_macron,[],1);

    dim_0 = size(alpha, 1);
    assert(numel(sigma_N) == 1);
    assert(numel(E_I) == 1);
    assert( size(alpha,1) == dim_0 );
    assert( size(beta,1) == dim_0 );
    assert( size(sigma_S,1) == dim_0 );
    assert( size(sigma_T,1) == dim_0 );
    assert( size(rho,1) == dim_0 );
    assert( size(rho_bar,1) == dim_0 );
    assert( size(sigma_rho,1) == dim_0 );
    assert( size(latin_small_letter_a_with_macron,1) == dim_0 );

    % E = 1/`σ_N`²`E_I` + ∑_(j for j>1) α_j²/`σ_S`_j² + ∑_(j for j>1) β_j²/`σ_T`_j²  + ∑_j (ρ_j-ρ̄_j)²/`σ_ρ`_j²

    sum_0 = 0;
    for j = 1:size(sigma_S, 1)
        if j > 1
          sum_0 = sum_0 + alpha(j).^2 / sigma_S(j).^2;
        end
    end
    sum_1 = 0;
    for j = 1:size(sigma_T, 1)
        if j > 1
          sum_1 = sum_1 + beta(j).^2 / sigma_T(j).^2;
        end
    end
    sum_2 = 0;
    for j = 1:size(sigma_rho, 1)
        sum_2 = sum_2 + (rho(j) - rho_bar(j)).^2 / sigma_rho(j).^2;
    end
    E = 1 / sigma_N.^2 * E_I + sum_0 + sum_1 + sum_2;
    output.E = E;
end
